import threading
import time

class Job:
    def __init__(self):
        self.ready = False

    def start(self):
        def work():
            self.ready = True
        threading.Thread(target=work, daemon=True).start()

    def wait_until_ready(self, timeout=1.0):
        deadline = time.time() + timeout
        while time.time() < deadline:
            if self.ready:
                return True
            time.sleep(0.05)
        return False
